#include <stdint.h>
// Scalar-basis prerequisite. No optimized C GEMM equivalence is implied.
__device__ float vc_bf(float x){unsigned b=__float_as_uint(x);if((b&0x7f800000u)!=0x7f800000u)b+=0x7fffu+((b>>16)&1);return __uint_as_float(b&0xffff0000u);}
__device__ float vc_half(unsigned short v){unsigned s=unsigned(v&32768)<<16,e=(v>>10)&31,f=v&1023;if(!e){if(!f)return __uint_as_float(s);e=113;while(!(f&1024)){f<<=1;e--;}return __uint_as_float(s|(e<<23)|((f&1023)<<13));}return __uint_as_float(s|((e==31?255:e+112)<<23)|(f<<13));}
extern "C" __global__ void ds4_v41_compressed_copy(float *dst,const float *src,unsigned n,unsigned clear){unsigned i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)dst[i]=clear?0:src[i];}
extern "C" __global__ void ds4_v41_compressed_ids(int *dst,const int *src,unsigned n){unsigned i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)dst[i]=src[i];}
extern "C" __global__ void ds4_v41_compressed_norm(float *x,const float *w,unsigned n){if(blockIdx.x||threadIdx.x)return;double sum=0;for(unsigned i=0;i<n;i++)sum+=double(x[i])*double(x[i]);float inv=__fdiv_rn(1.f,float(sqrt(double(__fadd_rn(float(sum/double(n)),1e-20f)))));for(unsigned i=0;i<n;i++)x[i]=vc_bf(__fmul_rn(__fmul_rn(x[i],inv),w[i]));}
extern "C" __global__ void ds4_v41_compressed_index(float *out,const float *x,const unsigned short *w){unsigned row=blockIdx.x*blockDim.x+threadIdx.x;if(row>=128)return;float sum=0;for(unsigned i=0;i<512;i++)sum=__fadd_rn(sum,__fmul_rn(x[i],vc_half(w[row*512+i])));out[row]=vc_bf(sum);}
extern "C" __global__ void ds4_v41_compressed_scores(float *scores,const float *q,const float *weights,const float *keys,unsigned n,unsigned position,unsigned ratio){unsigned key=blockIdx.x*8+(threadIdx.x>>5),lane=threadIdx.x&31;if(key>=n)return;if(key>=(position+1)/ratio){if(!lane)scores[key]=-__int_as_float(0x7f800000);return;}float total=0;for(unsigned h=0;h<32;h++){const float *x=q+h*128+lane,*k=keys+uint64_t(key)*128+lane;float a=__fadd_rn(__fmul_rn(x[0],k[0]),__fmul_rn(x[64],k[64]));float b=__fadd_rn(__fmul_rn(x[32],k[32]),__fmul_rn(x[96],k[96]));float d=__fadd_rn(a,b);for(unsigned step=16;step;step>>=1)d=__fadd_rn(d,__shfl_down_sync(0xffffffffu,d,step));total=__fadd_rn(total,__fmul_rn(fmaxf(d,0.f),weights[h]));}if(!lane)scores[key]=__fmul_rn(total,1.f/64);}
// Stable top-k: descending score, then ascending ID, including infinities.
// Deliberately serial and bounded; performance is not this slice's claim.
extern "C" __global__ void ds4_v41_compressed_pick(int *ids,float *scores,unsigned *mask,float *blocks,unsigned *used,unsigned n,unsigned layer){if(blockIdx.x||threadIdx.x)return;unsigned nb=(n+7)/8;float inf=__int_as_float(0x7f800000);if(layer==20){for(unsigned b=0;b<nb;b++){float v=-inf;for(unsigned j=b*8;j<n&&j<(b+1)*8;j++)v=fmaxf(v,scores[j]);blocks[b]=b+1==nb?inf:v;mask[b]=0;used[b]=0;}for(unsigned rank=0;rank<nb&&rank<2048;rank++){unsigned best=nb;for(unsigned b=0;b<nb;b++)if(!used[b]&&(best==nb||blocks[b]>blocks[best]))best=b;used[best]=1;mask[best]=1;}}
 if(layer>20)for(unsigned j=0;j<n;j++)if(!mask[j/8])scores[j]=-inf;
 for(unsigned j=0;j<n;j++)used[j]=0;
 for(unsigned rank=0;rank<n&&rank<512;rank++){unsigned best=n;for(unsigned j=0;j<n;j++)if(!used[j]&&(best==n||scores[j]>scores[best]))best=j;ids[rank]=int(best);used[best]=1;}}
extern "C" __global__ void ds4_v41_compressed_gather(float *out,const float *cache,const int *ids,unsigned n,unsigned top){unsigned row=blockIdx.x;if(row>=top)return;int id=ids[row];for(unsigned d=threadIdx.x;d<512;d+=blockDim.x)out[row*512+d]=id>=0&&unsigned(id)<n?cache[uint64_t(id)*512+d]:__int_as_float(0x7fffffff);}
